-- Q1 [Nernst Equation & Concentration Cells · easy · Skill 1 · 4C Electrochemistry (GC) · ans A] (g69)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Nernst Equation & Concentration Cells',
    $qt69$A galvanic cell is initially set up under standard conditions, so its potential equals the standard cell potential, \(E^{\circ}_{\text{cell}}\). The cell is then altered so that its reaction quotient becomes less than one (\(Q < 1\))—for example, by raising the concentration of a reactant ion or lowering the concentration of a product ion. The cell continues to operate at 298 K, where the Nernst equation takes the form \(E_{\text{cell}} = E^{\circ}_{\text{cell}} - \frac{0.0592}{n}\log Q\). Once \(Q < 1\), how does the new cell potential \(E_{\text{cell}}\) compare to the standard cell potential \(E^{\circ}_{\text{cell}}\)?$qt69$,
    $op69$[{"label":"A","text":"\\(E_{\\text{cell}}\\) is greater than \\(E^{\\circ}_{\\text{cell}}\\)."},{"label":"B","text":"\\(E_{\\text{cell}}\\) is less than \\(E^{\\circ}_{\\text{cell}}\\)."},{"label":"C","text":"\\(E_{\\text{cell}}\\) is equal to \\(E^{\\circ}_{\\text{cell}}\\)."},{"label":"D","text":"The comparison cannot be determined without knowing the value of \\(n\\)."}]$op69$::jsonb,
    'A',
    $ex69$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is A because when \(Q < 1\), \(\log Q\) is negative, so the Nernst correction term \(-\frac{0.0592}{n}\log Q\) becomes a positive quantity that adds to \(E^{\circ}_{\text{cell}}\); therefore \(E_{\text{cell}} = E^{\circ}_{\text{cell}} - \frac{0.0592}{n}\log Q > E^{\circ}_{\text{cell}}\), making the cell potential greater than the standard value. (Choice B) \(E_{\text{cell}}\) is less than \(E^{\circ}_{\text{cell}}\) only when \(Q > 1\), which makes \(\log Q\) positive and the correction term negative; this reverses the actual effect of \(Q < 1\). (Choice C) \(E_{\text{cell}}\) equals \(E^{\circ}_{\text{cell}}\) only at standard conditions where \(Q = 1\) and \(\log Q = 0\), so the correction term vanishes; this is not the case once \(Q\) is moved below one. (Choice D) The direction of the change does not depend on \(n\): regardless of the value of \(n\), the factor \(\frac{0.0592}{n}\) is positive, so the sign of the correction term is fixed by the sign of \(\log Q\) alone, and \(Q < 1\) always makes \(E_{\text{cell}}\) larger than \(E^{\circ}_{\text{cell}}\). Skill 1$ex69$,
    'easy', '4C', $cc69$Electrochemistry (GC)$cc69$, 'general-chemistry', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'reversed_relationship', $a69B$Applies the Q > 1 outcome (potential drops below standard) to a Q < 1 scenario, flipping the sign of the log term$a69B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a69C$Assumes the cell potential always equals the standard potential, ignoring that the Nernst correction term is nonzero whenever Q is not equal to 1$a69C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a69D$Overweights the appearance of n in the prefactor and wrongly concludes the direction of the shift is indeterminate, when n only scales magnitude, not sign$a69D$ FROM q;

-- Q2 [Nernst Equation & Concentration Cells · medium · Skill 2 · 4C Electrochemistry (GC) · ans B] (g70)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Nernst Equation & Concentration Cells',
    $qt70$A galvanic cell is constructed as \(\text{Zn(s)} \mid \text{Zn}^{2+}(1\ \text{M}) \parallel \text{Ag}^{+}(1\ \text{M}) \mid \text{Ag(s)}\), operating by the reaction \(\text{Zn(s)} + 2\,\text{Ag}^{+}(aq) \rightarrow \text{Zn}^{2+}(aq) + 2\,\text{Ag(s)}\), for which the reaction quotient is \(Q = \dfrac{[\text{Zn}^{2+}]}{[\text{Ag}^{+}]^{2}}\). Starting from these standard conditions, the \([\text{Ag}^{+}]\) in the cathode compartment is increased while \([\text{Zn}^{2+}]\) in the anode compartment is held fixed at \(1\ \text{M}\). According to the Nernst equation \(E_{\text{cell}} = E^{\circ}_{\text{cell}} - \frac{0.0592}{n}\log Q\) at 298 K, how does the measured cell voltage \(E_{\text{cell}}\) change?$qt70$,
    $op70$[{"label":"A","text":"\\(E_{\\text{cell}}\\) decreases, because raising \\([\\text{Ag}^{+}]\\) raises \\(Q\\), making the \\(-\\frac{0.0592}{n}\\log Q\\) term more negative."},{"label":"B","text":"\\(E_{\\text{cell}}\\) increases, because raising \\([\\text{Ag}^{+}]\\) lowers \\(Q\\), making the \\(-\\frac{0.0592}{n}\\log Q\\) term more positive."},{"label":"C","text":"\\(E_{\\text{cell}}\\) is unchanged, because \\(E^{\\circ}_{\\text{cell}}\\) is an intensive property that does not depend on ion concentrations."},{"label":"D","text":"\\(E_{\\text{cell}}\\) decreases, because adding \\(\\text{Ag}^{+}\\) supplies more product and drives the reaction toward completion, lowering its driving force."}]$op70$::jsonb,
    'B',
    $ex70$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is B because \([\text{Ag}^{+}]\) appears in the denominator of \(Q = \frac{[\text{Zn}^{2+}]}{[\text{Ag}^{+}]^{2}}\). Increasing \([\text{Ag}^{+}]\) while holding \([\text{Zn}^{2+}]\) fixed enlarges the denominator, so \(Q\) decreases (it drops below the standard value of 1). In the Nernst equation \(E_{\text{cell}} = E^{\circ}_{\text{cell}} - \frac{0.0592}{n}\log Q\), a smaller \(Q\) (now \(Q<1\)) gives \(\log Q < 0\), so the term \(-\frac{0.0592}{n}\log Q\) becomes positive and adds to \(E^{\circ}_{\text{cell}}\). Therefore \(E_{\text{cell}}\) increases. As a numerical check with \(E^{\circ}_{\text{cell}} = 1.56\ \text{V}\) and \(n=2\): at \([\text{Ag}^{+}]=1\ \text{M}\), \(Q=1\) and \(E_{\text{cell}}=1.56\ \text{V}\); at \([\text{Ag}^{+}]=10\ \text{M}\), \(Q=0.01\) and \(E_{\text{cell}} = 1.56 - \frac{0.0592}{2}\log(0.01) = 1.56 - (0.0296)(-2) = 1.56 + 0.059 \approx 1.62\ \text{V}\). This also matches Le Chatelier reasoning: \(\text{Ag}^{+}\) is a reactant, so adding it pushes the cell reaction forward and raises its spontaneous driving force (voltage). (Choice A) This reverses the dependence of \(Q\) on \([\text{Ag}^{+}]\); because \([\text{Ag}^{+}]\) sits in the denominator, increasing it lowers \(Q\) rather than raising it, so the sign of the change is inverted. (Choice C) This conflates \(E^{\circ}_{\text{cell}}\) with \(E_{\text{cell}}\); although \(E^{\circ}_{\text{cell}}\) is fixed and intensive, the actual \(E_{\text{cell}}\) depends on \(Q\) through the Nernst equation, so changing a concentration does shift the measured voltage. (Choice D) This mislabels \(\text{Ag}^{+}\) as a product when it is in fact a reactant, and although adding a reactant does increase the driving force, the choice draws the wrong conclusion (a decrease) from that step. Skill 2$ex70$,
    'medium', '4C', $cc70$Electrochemistry (GC)$cc70$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a70A$Treats increasing a denominator term as increasing Q$a70A$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a70C$Confuses fixed intensive E°cell with concentration-dependent Ecell$a70C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a70D$Misidentifies the reactant Ag+ as a product in Le Chatelier reasoning$a70D$ FROM q;

-- Q3 [Nernst Equation & Concentration Cells · medium · Skill 2 · 4C Electrochemistry (GC) · ans C] (g71)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Nernst Equation & Concentration Cells',
    $qt71$A galvanic concentration cell is constructed using two nickel electrodes, each immersed in a solution of \(\text{Ni}^{2+}\). One half-cell contains \(0.010\ \text{M}\ \text{Ni}^{2+}\) and the other contains \(0.10\ \text{M}\ \text{Ni}^{2+}\), connected by a salt bridge. The cell operates spontaneously by the half-reaction \(\text{Ni}^{2+} + 2e^- \rightarrow \text{Ni}\) (with \(n = 2\)). Using \(E_{\text{cell}} = E^{\circ}_{\text{cell}} - \frac{0.0592}{n}\log Q\) at 298 K, what is the cell voltage?$qt71$,
    $op71$[{"label":"A","text":"\\(-0.0296\\ \\text{V}\\)"},{"label":"B","text":"\\(+0.0592\\ \\text{V}\\)"},{"label":"C","text":"\\(+0.0296\\ \\text{V}\\)"},{"label":"D","text":"\\(0\\ \\text{V}\\)"}]$op71$::jsonb,
    'C',
    $ex71$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is C because in a concentration cell both electrodes are identical, so \(E^{\circ}_{\text{cell}} = 0\). The cell runs spontaneously by oxidizing Ni in the dilute half-cell (anode) and reducing \(\text{Ni}^{2+}\) in the concentrated half-cell (cathode), driving both compartments toward equal concentration. The reaction quotient is the ratio of the produced (anode, dilute) to consumed (cathode, concentrated) ion concentrations: \(Q = \frac{[\text{Ni}^{2+}]_{\text{anode}}}{[\text{Ni}^{2+}]_{\text{cathode}}} = \frac{0.010}{0.10} = 0.10\), so \(\log Q = \log(0.10) = -1\). With \(n = 2\), \(\frac{0.0592}{n} = \frac{0.0592}{2} = 0.0296\). Therefore \(E_{\text{cell}} = 0 - (0.0296)(-1) = +0.0296\ \text{V}\). The positive value confirms the process is spontaneous (\(E_{\text{cell}} > 0\), \(\Delta G < 0\)), as required for a working galvanic cell. (Choice A) \(-0.0296\ \text{V}\) has the correct magnitude but the wrong sign, obtained by inverting \(Q\) (placing the concentrated cell over the dilute cell) so that \(\log Q = +1\); this would describe a non-spontaneous direction and cannot be the operating voltage of a galvanic cell. (Choice B) \(+0.0592\ \text{V}\) results from using the full factor \(0.0592\) without dividing by \(n = 2\), i.e., omitting the two-electron stoichiometry in the Nernst prefactor. (Choice D) \(0\ \text{V}\) confuses the standard cell potential (\(E^{\circ}_{\text{cell}} = 0\) for any concentration cell) with the actual cell potential, ignoring that the concentration difference produces a nonzero Nernst correction. Skill 2$ex71$,
    'medium', '4C', $cc71$Electrochemistry (GC)$cc71$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a71A$Inverted Q (concentrated over dilute), flipping the sign$a71A$ FROM q
UNION ALL SELECT id, 'B', 'process_step_confusion', $a71B$Used full 0.0592 instead of dividing by n=2$a71B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a71D$Equated actual Ecell with E°cell = 0, ignoring Nernst term$a71D$ FROM q;

-- Q4 [Nernst Equation & Concentration Cells · medium · Skill 2 · 4C Electrochemistry (GC) · ans D] (g72)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Nernst Equation & Concentration Cells',
    $qt72$A silver concentration cell is constructed from two \(\text{Ag}/\text{Ag}^{+}\) half-cells connected by a wire and a salt bridge. Half-cell X contains \(0.020\ \text{M}\ \text{Ag}^{+}\) and half-cell Y contains \(0.40\ \text{M}\ \text{Ag}^{+}\); each half-cell holds an identical silver electrode. Because both electrodes are the same metal, \(E^{\circ}_{\text{cell}} = 0\), and the cell operates spontaneously as it drives the two \(\text{Ag}^{+}\) concentrations toward equality. As the cell discharges, which half-cell acts as the cathode, and in which direction do electrons travel through the external wire?$qt72$,
    $op72$[{"label":"A","text":"Half-cell X is the cathode; electrons flow through the wire from X to Y."},{"label":"B","text":"Half-cell X is the cathode; electrons flow through the wire from Y to X."},{"label":"C","text":"Half-cell Y is the cathode; electrons flow through the wire from Y to X."},{"label":"D","text":"Half-cell Y is the cathode; electrons flow through the wire from X to Y."}]$op72$::jsonb,
    'D',
    $ex72$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is D because a concentration cell reaches equilibrium when the two \(\text{Ag}^{+}\) concentrations become equal, so the spontaneous discharge must lower the high concentration and raise the low one. The concentrated half-cell, Y at \(0.40\ \text{M}\), accomplishes this by reduction: \(\text{Ag}^{+} + e^{-} \rightarrow \text{Ag}\) consumes \(\text{Ag}^{+}\) and pulls \([\text{Ag}^{+}]_{Y}\) downward. Reduction defines the cathode, so Y is the cathode. The dilute half-cell, X at \(0.020\ \text{M}\), is the anode, where oxidation \(\text{Ag} \rightarrow \text{Ag}^{+} + e^{-}\) raises \([\text{Ag}^{+}]_{X}\). Electrons are always released at the anode and travel through the external wire to the cathode, so they flow from X (anode) to Y (cathode). This is consistent with the Nernst equation: taking the dilute cell as anode and concentrated cell as cathode gives \(Q = [\text{Ag}^{+}]_{\text{anode}}/[\text{Ag}^{+}]_{\text{cathode}} = 0.020/0.40 < 1\), so \(E_{\text{cell}} = 0 - \frac{0.0592}{1}\log Q > 0\), confirming a spontaneous (galvanic) process. (Choice A) This mislabels the anode X as the cathode while keeping the correct anode-to-cathode electron path; the electron direction matches a process where X receives electrons, which contradicts X being the cathode in that statement. (Choice B) This reverses both assignments: it names the dilute cell X as the cathode, which would force the high-concentration side to dissolve metal and the low side to plate out, driving the concentrations further apart and away from equilibrium, the opposite of spontaneous behavior. (Choice C) This correctly identifies Y as the cathode but reverses the electron-flow direction; electrons leave the anode and move toward the cathode through the wire, so they flow from X to Y, not from Y to X. Skill 2$ex72$,
    'medium', '4C', $cc72$Electrochemistry (GC)$cc72$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a72A$Keeps correct electron direction but mislabels the anode half-cell as the cathode$a72A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a72B$Treats the dilute half-cell as the cathode, driving concentrations apart instead of toward equilibrium$a72B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a72C$Correct cathode but reverses external electron flow (cathode-to-anode instead of anode-to-cathode)$a72C$ FROM q;

-- Q5 [Nernst Equation & Concentration Cells · medium · Skill 2 · 4C Electrochemistry (GC) · ans A] (g73)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Nernst Equation & Concentration Cells',
    $qt73$A galvanic concentration cell is built from two lead electrodes, one dipping into \(0.0050\ \text{M}\ \text{Pb}^{2+}\) and the other into \(0.25\ \text{M}\ \text{Pb}^{2+}\), connected by a salt bridge. The cell reaction is \(\text{Pb}^{2+} + 2e^- \rightleftharpoons \text{Pb}(s)\) at each electrode, for which \(E^{\circ}_{\text{cell}} = 0\), yet a voltmeter initially reads a positive voltage of about \(+0.050\ \text{V}\) that slowly decreases toward zero as the cell operates (using \(E_{\text{cell}} = E^{\circ}_{\text{cell}} - \frac{0.0592}{n}\log Q\) at \(298\ \text{K}\)). Which statement best explains both the initial positive reading and its decline to zero?$qt73$,
    $op73$[{"label":"A","text":"Because \\(E^{\\circ}_{\\text{cell}} = 0\\) only removes the standard term, the nonzero reading comes entirely from the \\(-\\frac{0.0592}{n}\\log Q\\) term created by the concentration difference; reduction proceeds in the concentrated half-cell and oxidation in the dilute one, and as those concentrations converge \\(Q \\rightarrow 1\\) so \\(E_{\\text{cell}} \\rightarrow 0\\) at equilibrium."},{"label":"B","text":"Because the two half-cells use the same metal, no electron transfer is thermodynamically possible; the positive reading comes from the salt bridge, and it falls as the salt bridge is depleted of ions."},{"label":"C","text":"Because both electrodes are identical lead, \\(E^{\\circ}_{\\text{cell}} = 0\\); the meter reads zero from the start, and the small positive deflection is only instrument drift that settles back to zero as the device stabilizes."},{"label":"D","text":"Because \\(E^{\\circ}_{\\text{cell}} = 0\\), the reaction is already at equilibrium; the positive reading reflects the dilute half-cell acting as the cathode, and the voltage falls as \\(\\text{Pb}^{2+}\\) is consumed there until that side runs out."}]$op73$::jsonb,
    'A',
    $ex73$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is A because the standard cell potential and the actual cell potential are two distinct quantities linked by the Nernst equation, \(E_{\text{cell}} = E^{\circ}_{\text{cell}} - \frac{0.0592}{n}\log Q\). In a concentration cell both electrodes are the same metal in the same redox couple (\(\text{Pb}^{2+} + 2e^- \rightleftharpoons \text{Pb}\)), so the cathode and anode have identical standard reduction potentials and \(E^{\circ}_{\text{cell}} = E^{\circ}_{\text{red,cathode}} - E^{\circ}_{\text{red,anode}} = 0\). That makes \(E^{\circ}_{\text{cell}} = 0\) drop out, leaving the entire driving force in the \(-\frac{0.0592}{n}\log Q\) term, which is nonzero only because the two \(\text{Pb}^{2+}\) concentrations differ. The system lowers its free energy by diluting the concentrated solution and concentrating the dilute one, so reduction (\(\text{Pb}^{2+}\) plated onto the electrode) occurs at the concentrated \(0.25\ \text{M}\) cathode while oxidation (\(\text{Pb}\) dissolving) occurs at the dilute \(0.0050\ \text{M}\) anode. With \(Q = [\text{Pb}^{2+}]_{\text{anode}}/[\text{Pb}^{2+}]_{\text{cathode}} = 0.0050/0.25 = 0.020\) and \(n = 2\), \(E_{\text{cell}} = 0 - \frac{0.0592}{2}\log(0.020) = -(0.0296)(-1.699) = +0.050\ \text{V}\), a positive value confirming a spontaneous galvanic process (\(\Delta G < 0\)). As the cell runs, the concentrated side falls and the dilute side rises, so \(Q\) climbs toward \(1\), \(\log Q \rightarrow 0\), and \(E_{\text{cell}} \rightarrow 0\); the voltage reaches zero precisely when the two concentrations are equal, which is the equilibrium state for this cell. (Choice B) Identical electrode metals do not forbid electron transfer; the differing \(\text{Pb}^{2+}\) activities provide a genuine thermodynamic driving force, and the salt bridge merely completes the circuit rather than generating the voltage. (Choice C) The positive reading is not instrument drift but a real, calculable potential from the concentration gradient; \(E^{\circ}_{\text{cell}} = 0\) does not force \(E_{\text{cell}} = 0\) because the logarithmic Nernst term remains. (Choice D) A nonzero measured potential means the cell is not at equilibrium; moreover the assignment is reversed, since reduction occurs at the concentrated half-cell (the cathode) and the dilute half-cell is the anode, so the voltage decays as the concentrations equalize, not because one side is depleted of ions. Skill 2$ex73$,
    'medium', '4C', $cc73$Electrochemistry (GC)$cc73$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'partial_truth', $a73B$Correctly notes the electrodes are the same metal but wrongly concludes no electron transfer is possible and attributes the voltage to the salt bridge rather than the concentration difference.$a73B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a73C$Treats E°cell = 0 as forcing E_cell = 0 and dismisses the real Nernst-term voltage as mere instrument drift, ignoring the concentration-gradient driving force.$a73C$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a73D$Reverses the electrode roles (calls the dilute side the cathode) and conflates E°cell = 0 with the cell being at equilibrium, explaining the decay by ion depletion instead of concentration equalization.$a73D$ FROM q;

-- Q6 [Nernst Equation & Concentration Cells · hard · Skill 2 · 4C Electrochemistry (GC) · ans B] (g74)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Nernst Equation & Concentration Cells',
    $qt74$A galvanic Daniell-type cell is assembled at \(298\ \text{K}\) as \(\text{Zn}(s)\,|\,\text{Zn}^{2+}(0.0010\ \text{M})\,||\,\text{Cu}^{2+}(0.10\ \text{M})\,|\,\text{Cu}(s)\), for which the standard cell potential is \(E^{\circ}_{\text{cell}} = +1.10\ \text{V}\) and the cell transfers \(n = 2\) electrons. Using the Nernst equation in the form \(E_{\text{cell}} = E^{\circ}_{\text{cell}} - \frac{0.0592}{n}\log Q\), what is the cell potential under these non-standard conditions?$qt74$,
    $op74$[{"label":"A","text":"\\(+1.04\\ \\text{V}\\)"},{"label":"B","text":"\\(+1.16\\ \\text{V}\\)"},{"label":"C","text":"\\(+1.22\\ \\text{V}\\)"},{"label":"D","text":"\\(+1.10\\ \\text{V}\\)"}]$op74$::jsonb,
    'B',
    $ex74$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is B because the reaction quotient must be assembled from the correct cell reaction and then carried through the Nernst equation with attention to the sign of \(\log Q\). The cell notation places \(\text{Zn}\) on the left (anode, oxidation: \(\text{Zn} \rightarrow \text{Zn}^{2+} + 2e^-\)) and \(\text{Cu}\) on the right (cathode, reduction: \(\text{Cu}^{2+} + 2e^- \rightarrow \text{Cu}\)), so the overall reaction is \(\text{Zn}(s) + \text{Cu}^{2+} \rightarrow \text{Zn}^{2+} + \text{Cu}(s)\). For this reaction \(Q = \frac{[\text{Zn}^{2+}]}{[\text{Cu}^{2+}]}\) (the pure solids are excluded), so \(Q = \frac{0.0010}{0.10} = 0.010 = 10^{-2}\) and \(\log Q = -2\). With \(n = 2\), the prefactor is \(\frac{0.0592}{2} = 0.0296\ \text{V}\). Substituting, \(E_{\text{cell}} = 1.10 - (0.0296)(-2) = 1.10 - (-0.0592) = 1.10 + 0.0592 = 1.1592 \approx +1.16\ \text{V}\). The result is physically sensible: \(Q < 1\) means products are below their standard amounts, which favors the forward reaction and pushes \(E_{\text{cell}}\) above \(E^{\circ}_{\text{cell}}\). (Choice A) \(+1.04\ \text{V}\) results from building the quotient upside-down as \(Q = \frac{[\text{Cu}^{2+}]}{[\text{Zn}^{2+}]} = \frac{0.10}{0.0010} = 10^{2}\), giving \(\log Q = +2\) and \(E_{\text{cell}} = 1.10 - (0.0296)(2) = 1.04\ \text{V}\); this inverts the reactant/product placement in \(Q\). (Choice C) \(+1.22\ \text{V}\) results from omitting the division by \(n\), i.e. using \(0.0592\) rather than \(\frac{0.0592}{2}\): \(1.10 - (0.0592)(-2) = 1.10 + 0.1184 = 1.2184 \approx 1.22\ \text{V}\), which double-counts the correction for a two-electron cell. (Choice D) \(+1.10\ \text{V}\) results from reporting \(E^{\circ}_{\text{cell}}\) unchanged, treating the cell as if it were at standard conditions and ignoring the Nernst correction even though the ion concentrations are not \(1\ \text{M}\). Skill 2$ex74$,
    'hard', '4C', $cc74$Electrochemistry (GC)$cc74$, 'general-chemistry', 2, 160
  ) RETURNING id
)
